#include <stdio.h>
int main(){
    int count = 0;
    for(int i = 2; i <= 50; i++){
        int isPrime = 1;
        for(int j = 2; j*j <= i; j++){
            if(i % j == 0){ isPrime = 0; break; }
        }
        if(isPrime) count++;
    }
    printf("%d", count);
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int value; struct Node* next; } Node;

Node* insert(Node* head, int value) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->value = value;
    n->next = head;
    return n;
}

Node* deleteValue(Node* head, int value) {
    Node dummy; dummy.next = head;
    Node *prev = &dummy, *curr = head;
    while (curr != NULL) {
        if (curr->value == value) {
            prev->next = curr->next;
            free(curr);
            break;
        }
        prev = curr;
        curr = curr->next;
    }
    return dummy.next;
}

int main() {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = insert(head, i);
    head = deleteValue(head, 3);
    for (Node* c = head; c != NULL; c = c->next) printf("%d", c->value);
    return 0;
}

