#include <stdio.h>

int main(){
    int arr[5] = {5, 2, 9, 1, 6};
    int swaps = 0;
    for (int i = 0; i < 4; i++) {
        if (arr[i] > arr[i+1]) {
            int t = arr[i];
            arr[i] = arr[i+1];
            arr[i+1] = t;
            swaps++;
        }
    }
    printf("%d\n", swaps);
    for (int i = 0; i < 5; i++) printf("%d", arr[i]);
    return 0;
}

